Creating blob URLs with `URL.createObjectURL()` without cleanup causes memory leaks. Each blob URL created here persists in memory until explicitly revoked.

Add cleanup to revoke the blob URLs after validation or on component unmount:

```tsx
const handleDrop = useCallback(
    (event: DragEvent) => {
        const files = Array.from(event.dataTransfer?.files ?? []);
        if (files.length === 0) {
            return;
        }
        const blobUrls: string[] = [];
        for (const file of files) {
            const blobUrl = URL.createObjectURL(file);
            blobUrls.push(blobUrl);
            // eslint-disable-next-line no-param-reassign
            file.uri = blobUrl;
        }
        validateFiles(files as FileObject[], Array.from(event.dataTransfer?.items ?? []));
        // Clean up blob URLs after validation
        blobUrls.forEach(url => URL.revokeObjectURL(url));
    },
    [validateFiles],
);
```

